  const ref=host.querySelector('.stl-shade');host.insertBefore(gc,ref);host.insertBefore(oc,ref);const o=oc.getContext("2d");
  const VS=`#version 300 es
in vec2 p;out vec2 uv0;void main(){uv0=p*.5+.5;gl_Position=vec4(p,0,1);}`;
