  function resize(g){geo=g;const dpr=Math.min(devicePixelRatio||1,1.5),W=g.vw*g.scale,H=g.vh*g.scale;
    for(const c of [gc,oc]){Object.assign(c.style,{width:W+"px",height:H+"px",left:g.left+"px"})}
    gc.width=Math.round(W*dpr);gc.height=Math.round(H*dpr);oc.width=Math.round(W);oc.height=Math.round(H);gl.viewport(0,0,gc.width,gc.height)}
