      o.fillStyle=hs;o.globalAlpha=.35;o.fillRect(sx-oc.width*.32,sy-3,oc.width*.64,6);o.globalAlpha=1;o.fillRect(sx-oc.width*.32,sy-1,oc.width*.64,2);
