  const ROADS=[
    {pts:[[180, 149], [195, 151], [210, 154], [225, 157], [238, 161], [250, 165], [260, 169], [268, 173], [273, 177], [271, 181], [263, 182], [254, 182], [243, 184], [230, 186], [215, 188], [200, 191], [185, 195], [170, 198]],n:0,sp:12,a:1},
    {pts:[[403.6, 121.3], [398.0, 121.6], [390.3, 122.3], [383.3, 123.2], [377.1, 125.0], [372.0, 127.0], [372.5, 129.4], [378.2, 131.3], [384.9, 133.2], [391.8, 134.7], [394.4, 136.8], [393.7, 138.5]],n:9,sp:6,a:.85}];
  for(const r of ROADS){let L=0;r.seg=[];for(let i=0;i<r.pts.length-1;i++){const[a,c]=[r.pts[i],r.pts[i+1]],l=Math.hypot(c[0]-a[0],c[1]-a[1]);r.seg.push([L,l,a,c]);L+=l}r.L=L;
    r.cars=Array.from({length:r.n},(_,i)=>({s:R()*L,dir:r.oneway?1:(i%2?1:-1)}))}
  const along=(r,s)=>{for(const[L0,l,a,c]of r.seg)if(s<=L0+l){const t=(s-L0)/l,dx=c[0]-a[0],dy=c[1]-a[1],n=Math.hypot(dx,dy);return[a[0]+dx*t,a[1]+dy*t,-dy/n,dx/n]}const e=r.pts[r.pts.length-1];return[e[0],e[1],0,1]};
  const STRANDS=[[130,79,13,0,"#1b1f44"],[129,82,15,1.3,"#1b1f44"],[128,85,14,2.1,"#b0306e"],[127,88,12,3.3,"#1b1f44"],[128,91,10,4.2,"#37e6ff"]];
  const BEAMS=[{x:207,y:46,per:13.7,ph:0,sw:.55,bias:-.12,mode:"sweep",w:.075,a:.26,c:"#b8d4ff"},{x:262,y:50,per:23.3,ph:.37,sw:.42,bias:.18,mode:"pause",w:.065,a:.22,c:"#ffb8e4"},{x:176,y:24,per:7.9,ph:.71,sw:.3,bias:-.05,mode:"wobble",w:.06,a:.18,c:"#b8d4ff"}];
  const beamAng=(L,t)=>{const q=t/L.per+L.ph,s=Math.sin(q*6.2832);let v=s;if(L.mode==="pause")v=Math.sign(s)*Math.min(1,Math.abs(s)*1.8);if(L.mode==="wobble")v=.75*s+.25*Math.sin(q*6.2832*2.7+1.3);return -Math.PI/2+L.bias+v*L.sw};
