    const WATER=[400,142,80,14],LANT=[290,150,190,56],FAIRY=[0,20,100,60],ROADBOX=[[165,140,115,62],[360,104,120,40]];
    const nearLeg=new Set();for(const q of A.legPx)for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++)nearLeg.add((q.x+dx)+","+(q.y+dy));
